// --- Get AI response ---
let aiBody = $input.first().json.content ?? '';

// Convert escaped sequences like "\n" into real newlines
aiBody = aiBody.replace(/\\n/g, '\n');

// Normalize to LF first
aiBody = aiBody
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n');

// --- Get original email data ---
const trigger = $node["Email Trigger (IMAP)"].json;

const subject = trigger.subject ?? '';
const from = trigger.from ?? '';
let original = trigger.textPlain ?? '';

// Convert escaped sequences in original mail too
original = original.replace(/\\n/g, '\n');

// Normalize original to LF
original = original
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n');

// --- Build full message using LF internally ---
let fullText =
`Sehr geehrter Herr/Frau ${from}

${aiBody}



Viele Grüße
i.A. Praktikantenamt


--------------------------
Original-E-Mail:
Betreff: ${subject}
Von: ${from}

${original}`;

// Final normalization: convert everything to strict CRLF
fullText = fullText
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .replace(/\n/g, '\r\n');

return {
  text: fullText
};

